ch(long whereToStop = kImmediate);		virtual void 	ContinueSpeech();	// ---------------------------------------------------------	// Say It	// ---------------------------------------------------------				void 	Say(float number, short digitsDesired, bool wait); 	//float				void 	Say(long number, bool wait); 						//integer				void 	Say(const char* str, bool wait); 					//string						void 	Say(const TEHandle TEHdl, bool wait); 				//TEHandle		virtual void 	Say(const void *textBuf, short firstByte, short byteCount, bool wait);		//text, the workhorse. The other Say methods forward into here.		// ---------------------------------------------------------	// Speech Speed	// ---------------------------------------------------------	virtual void	SetSpeechRateModifier(Fixed newModifier);		virtual void	SetSpeechRate(Fixed newRate);		virtual void 	SpeakFaster();		virtual void 	SpeakSlower();	protected:	Fixed			fSpeechRateModifier;	SpeechChannel	fSpeechChannel;	Fixed			fSpeechRate;};#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/25/96	[1345531] Added #include "UClassDesc.h", "UStreamable.h" and							"UCoreUtilities.h" for noload buids.		05/06/96	Changed parm to constructor to CStr63_AC. Make pointer parms to							MSpeakable::Say const and made several methods const.		05/06/96	Created, Initial checkin.		----- R10 -----*/